def about_page():
    head=f'''<section class="page-hero about-page-hero"><div class="shell about-hero-grid"><div><div class="eyebrow"><span class="eyebrow-line"></span>ABOUT / ACADEMIC & PROFESSIONAL CV</div><h1>Curiosity, <em>with purpose.</em></h1><p>I am an AI researcher, technologist, and founder working where intelligent systems meet complex human challenges. My path has moved through software engineering, industry data science, autonomous vehicles, research, and public-safety innovation.</p>{button('Start a conversation','mailto:'+S['email'],'btn-primary','↗')}</div><aside class="about-focus-panel" aria-label="Research and professional focus"><span class="about-focus-eyebrow">RESEARCH / INNOVATION / IMPACT</span><h2>Engineering intelligence for the public good.</h2><p>Research at Concordia University. Innovation through Zenext AI. A focus on AI, autonomous systems, and dependable technologies for first responders.</p><span class="about-focus-location">MONTRÉAL, CANADA</span></aside></div></section>'''
    bio=f'''<section class="section shell" id="biography">{section_head('BACKGROUND','A different kind <em>of perspective.</em>')}<div class="two-col-body about-biography"><p>I am pursuing my Ph.D. in Information Systems Engineering at Concordia University in Montréal, with research in artificial intelligence, machine learning, and autonomous decision support. My interests include reinforcement learning, intelligent transportation systems, human-supervised UAVs, and reliable software for critical settings.</p><p>As Founder and CEO of Zenext AI, I lead R&D focused on hands-free AI interfaces and connected technologies for first responders. Earlier roles with Motional, Cummins, State Street, System Soft Technologies, and other organizations shaped how I approach data, software, mobility, and cross-disciplinary problem solving. I aim to bridge research with technology that is understandable, testable, and socially relevant.</p></div><div class="profile-facts"><div><span>CURRENTLY</span><strong>Ph.D. Candidate</strong><small>Concordia University</small></div><div><span>ALSO</span><strong>Founder & CEO</strong><small>Zenext AI</small></div><div><span>RESEARCH FOCUS</span><strong>Intelligent Systems</strong><small>AI, autonomy & public safety</small></div><div><span>BASED IN</span><strong>Montréal</strong><small>Québec, Canada</small></div></div></section>'''
    exp=f'''<section class="section soft-section" id="experience"><div class="shell">{section_head('PROFESSIONAL EXPERIENCE','The work behind <em>the research.</em>','A non-linear journey across research leadership, engineering R&D, financial data science, and autonomous mobility.')}<div class="timeline">{''.join(f'<article class="timeline-item"><div class="timeline-when">{e(x["period"])}<span class="timeline-dot"></span></div><div class="timeline-content"><div class="timeline-type">{e(x["type"])}</div><h3>{e(x["role"])}</h3><p class="timeline-org">{e(x["organization"])} <span>· {e(x["location"])}</span></p><p>{e(x["description"])}</p></div></article>' for x in D['experience'])}</div></div></section>'''
    edu=f'''<section class="section shell" id="education">{section_head('EDUCATION','An interdisciplinary <em>foundation.</em>')}<div class="education-list">{''.join(f'<div class="education-row"><span>{e(x["year"])}</span><div><h3>{e(x["degree"])}</h3><p>{e(x["school"])}</p><small>{e(x["note"])}</small></div></div>' for x in D['education'])}</div></section>'''
    aw=f'''<section class="section soft-section" id="awards"><div class="shell">{section_head('RECOGNITION','Research & <em>innovation honors.</em>')}<div class="award-cards">{''.join(f'<article><span class="award-year">{e(x["year"])}</span><span class="award-kind">{e(x["kind"])}</span><h3>{e(x["name"])}</h3><p>{e(x["detail"])}</p></article>' for x in D['awards'])}</div></div></section>'''
    service=f'''<section class="section shell" id="teaching">{section_head('TEACHING, SERVICE & OUTREACH','Giving knowledge <em>back.</em>')}<div class="service-grid"><div><h3>Teaching interests</h3><p>Introductory programming, data structures and algorithms, database systems, software engineering, AI, machine learning, applied data science, IoT, human–computer interaction, and responsible computing.</p><p>My preferred approach combines progressive hands-on exercises, reproducible experiments, collaborative projects, and examples drawn from real systems.</p></div><div><h3>Academic service</h3><ul><li>Editorial Board Member, <em>International Journal of Robotics and Automation Technology</em> (since 2025)</li><li>Technical program committee and peer-review service across IEEE CCWC, IEEE World AI IoT Congress, and IEEE IEMCON</li><li>Industry Forum and Exhibition Chair, ISNCC 2025</li><li>Invited research and practitioner talks at IEEE, NIST/PSCR, and international academic events</li></ul></div></div></section>'''
    contact=f'''<section class="about-contact"><div class="shell"><div><span class="eyebrow">COLLABORATE / CONNECT</span><h2>Let's do meaningful work together.</h2></div><div><p>Research collaboration, teaching, technical speaking, interdisciplinary partnerships, and public-safety R&D.</p><a class="text-link" href="mailto:{e(S['email'])}">{e(S['email'])} {arrow()}</a></div></div></section>'''
    return layout('About','About & CV','Academic background, industry experience, awards, teaching, and career of Swarnamouli Majumdar, researcher and Founder of Zenext AI.',head+bio+exp+edu+aw+'''<section class="section shell about-award-photo"><div><span class="eyebrow">FROM THE ARCHIVE</span><h2>A moment of recognition.</h2><p>Receiving the Best Paper Award at InCIT 2025 for research on mission adaptation and distributed cognition.</p><a class="text-link" href="gallery.html#incit-2025">View award and photographs ↗</a></div><img src="assets/photos/incit-2025-award-ceremony.jpg" alt="Swarnamouli Majumdar receiving the InCIT 2025 Best Paper Award" loading="lazy"></section>'''+service+contact)



